sp_widget.client_script:
function ($scope, $rootScope) {
    var chartDividaPublicaTotalInstance = null;

    $scope.anoSelecionadoDividaPublicaTotal = "";
    $scope.exibirGraficoDividaPublicaTotal = false;
    $scope.dadosDividaPublicaTotal = [];

  function carregarDadosDividaPublicaTotal() {
    var filtros = {
        ano: $scope.anoSelecionadoDividaPublicaTotal || ""
    };

    $scope.server.get(filtros).then(function (response) {
        $scope.dadosDividaPublicaTotal = response.data.dadosDividaPublicaTotal || [];
        setTimeout(function () {
            inicializarGraficoDividaPublicaTotal($scope.dadosDividaPublicaTotal);
        }, 300); // 300ms de atraso
    });
}


    $rootScope.$on('filtroAnoIndicadoresSelecionado', function (event, ano) {
        $scope.anoSelecionadoDividaPublicaTotal = ano;
        carregarDadosDividaPublicaTotal();
    });

    carregarDadosDividaPublicaTotal();

    function inicializarGraficoDividaPublicaTotal(listaDividaPublicaTotal) {
        if (!listaDividaPublicaTotal || listaDividaPublicaTotal.length === 0) {
            if (chartDividaPublicaTotalInstance) {
                chartDividaPublicaTotalInstance.destroy();
                chartDividaPublicaTotalInstance = null;
            }
            $scope.exibirGraficoDividaPublicaTotal = false;
            $scope.$applyAsync();
            return;
        }

        $scope.exibirGraficoDividaPublicaTotal = true;
        $scope.$applyAsync();

        var labels = [];
        var estoqueTotalData = [];

        listaDividaPublicaTotal.forEach(function (item) {
            labels.push(item.ano);
            estoqueTotalData.push(item.estoqueTotal);
        });

        var canvas = document.getElementById('graficoDividaPublicaTotal');
        if (!canvas) {
            console.error("Elemento canvas 'graficoDividaPublicaTotal' não encontrado.");
            return;
        }

        var ctx = canvas.getContext('2d');

        if (chartDividaPublicaTotalInstance) {
            chartDividaPublicaTotalInstance.destroy();
        }

        chartDividaPublicaTotalInstance = new Chart(ctx, {
            type: 'bar',
            data: {
                labels: labels,
                datasets: [
                    {
                        label: 'Estoque Total',
                        data: estoqueTotalData,
                        backgroundColor: '#6BB7F0',
                        borderColor: '#6BB7F0',
                        borderWidth: 1,
                        yAxisID: 'y'
                    }
                ]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    x: {
                        title: {
                            display: true,
                            text: 'Ano'
                        }
                    },
                    y: {
                        beginAtZero: true,
                        title: {
                            display: true,
                            text: 'Valores (em R$)'
                        }
                    }
                },
                plugins: {
                    legend: {
                        display: true,
                        position: 'top'
                    },
                    tooltip: {
                        callbacks: {
                            label: function (context) {
                                var valor = context.parsed.y || 0;
                                // Formatar número para padrão brasileiro
                                var valorFormatado = valor.toFixed(2)
                                    .replace('.', ',')
                                    .replace(/\B(?=(\d{3})+(?!\d))/g, '.');
                                return context.dataset.label + ': R$ ' + valorFormatado;
                            }
                        }
                    }
                }
            }
        });
    }
}

sp_widget.css:
canvas {
  display: block;
  margin: 0 auto;
}

h3, div, span {
 font-family: 'Roboto Flex', sans-serif;
}

/* --- Media Queries para Responsividade --- */

/* Telas Pequenas (Mobile S, M, L - até 767px) */
@media (max-width: 767px) {
  canvas {
    max-width: 90%; /* Ajustar a largura máxima do canvas */
  }
  h3 {
    font-size: 1rem; /* Ajustar o tamanho da fonte do título */
  }
}

/* Tablets (iPad Mini, iPad Air, Surface Duo, Galaxy Z Fold 5 - 768px até 1023px) */
@media (min-width: 768px) and (max-width: 1023px) {
  canvas {
    max-width: 80%;
  }
  h3 {
    font-size: 1.1rem;
  }
}

/* Laptops e Telas Maiores (iPad Pro, Surface Pro 7, Laptops, 4K - 1024px em diante) */
@media (min-width: 1024px) {
  canvas {
    max-width: none;
  }
  h3 {
  }
}

/* Ajustes para o Surface Duo (540x720) */
@media (width: 540px) and (height: 720px) {
    canvas {
        max-width: 95%;
    }
}

/* Ajustes para Galaxy Z Fold 5 (max-width: 350px) */
@media (max-width: 350px) {
    h3 {
        font-size: 0.9rem;
    }
}
@import url('https://fonts.googleapis.com/css2?family=Roboto+Flex:opsz,wght@8..144,100..1000&display=swap');

* {
  box-sizing: border-box;
}

.report-widget {
  border-radius: 12px;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.08);
  background-color: #fff;
  margin-top: 24px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  font-family: 'Roboto Flex', sans-serif;
  transition: opacity 0.5s ease-in-out, transform 0.5s ease-in-out, visibility 0.5s ease-in-out;
}

.panel-heading {
  background-color: #e0e0e0;
  padding: 12px 16px;
  border-bottom: 1px solid #ccc;
  border-top-left-radius: 12px;
  border-top-right-radius: 12px;
}

.panel-title {
  margin: 0;
  font-size: 1.6rem;
  color: #333;
  text-align: center;
}

.panel-body {
  padding: 16px;
  flex: 1;
  width: 100%;
  font-size: 1.2em;
  text-align: center;
}

/* Animação de entrada e saída */
.mensagem {
  opacity: 0;
  visibility: hidden;
  transform: translateY(20px);
  height: 0;
  overflow: hidden;
}

.mensagem.show {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
  height: auto;
}

/* Responsividade */
@media (max-width: 767px) {
  .report-widget {
    margin-top: 1rem;
  }
  .panel-title {
    font-size: 1.4rem;
  }
  .panel-body {
    padding: 8px;
  }
}

@media (min-width: 768px) and (max-width: 1023px) {
  .panel-title {
    font-size: 1.5rem;
  }
}

@media (min-width: 1024px) {
  .panel-title {
    font-size: 1.6rem;
  }
}

@media (min-width: 1280px) {
  .panel-heading {
    padding: 14px 18px;
  }
  .panel-body {
    padding: 20px;
  }
}

sp_widget.script:
(function() {
    input = input || {};
    var anoFiltro = input.ano || "";

    var gr = new GlideRecord('x_sded9_portal_t_0_u_divida_publica');
    if (anoFiltro !== "") {
        gr.addQuery('u_ano', anoFiltro);
    }
    gr.orderBy('u_ano');
    gr.query();

    var listaDividaPublicaTotal = [];

    while (gr.next()) {
        listaDividaPublicaTotal.push({
            ano: gr.getValue('u_ano'),
            estoqueTotal: parseFloat(gr.getValue('u_estoque_divida_publica_total')) / 1 || 0
        });
    }

    data.dadosDividaPublicaTotal = listaDividaPublicaTotal;
})();
